function roomContent(a){
 let content=`<div class="room-head"><span class="room-label">${String(a.id).padStart(2,'0')} · ${a.name}</span><span class="room-code">${a.type}</span></div><span class="room-sub">${a.agents.length} AGENTS / ONLINE</span>`;
 if(a.groups){let gx=15,gy=60; a.groups.forEach((g,gi)=>{content+=`<div style="position:absolute;left:${gx+gi*220}px;top:48px;width:200px;border-top:1px solid ${a.color}55;padding-top:5px;font:7px DM Mono;color:${a.color}">${g[0]}</div>`;g.slice(1,10).forEach((n,i)=>{const x=gx+gi*220+(i%3)*62,y=gy+38+Math.floor(i/3)*70;content+=sprite(n,x,y,a.color,i)});});}
 else {a.agents.slice(0,10).forEach((n,i)=>{let cols=Math.max(2,Math.floor((a.w-25)/68));let x=18+(i%cols)*68,y=62+Math.floor(i/cols)*70;content+=sprite(n,x,y,a.color,i)});}
 return content;
}
