function drawNetwork(){const svg=document.querySelector('#nodeLayer'),center=a=>[a.x+a.w/2,a.y+a.h/2],links=[[1,2,'feedback'],[3,2,''],[7,2,''],[2,4,'risk'],[5,4,'risk'],[9,4,'risk'],[4,6,'risk'],[6,2,''],[8,6,''],[7,4,'risk']];let html='<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#42d7d0"/></marker></defs>';links.forEach(([f,t,k],i)=>{const [x1,y1]=center(areas[f-1]),[x2,y2]=center(areas[t-1]),mx=(x1+x2)/2;const d=`M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}`;html+=`<path id="edge${i}" class="network-path ${k}" d="${d}" marker-end="url(#arrow)"/><circle class="packet" r="4"><animateMotion dur="${2.2+i%3*.5}s" repeatCount="indefinite"><mpath href="#edge${i}"/></animateMotion></circle>`});areas.forEach(a=>{const [x,y]=center(a);html+=`<circle class="network-node" cx="${x}" cy="${y}" r="6"/>`});svg.innerHTML=html}drawNetwork();
