let scale=.78,tx=25,ty=55,drag=false,sx=0,sy=0,stx=0,sty=0;const floor=document.querySelector('#floor'),vp=document.querySelector('#viewport');
function apply(){floor.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;document.querySelector('#zoomLabel').textContent=Math.round(scale*100)+'%'}
function setScale(v,cx=vp.clientWidth/2,cy=vp.clientHeight/2){let ns=Math.max(.42,Math.min(1.5,v));tx=cx-(cx-tx)*(ns/scale);ty=cy-(cy-ty)*(ns/scale);scale=ns;apply()}
vp.addEventListener('wheel',e=>{e.preventDefault();const r=vp.getBoundingClientRect();setScale(scale*(e.deltaY>0?.9:1.1),e.clientX-r.left,e.clientY-r.top)},{passive:false});vp.onpointerdown=e=>{if(e.target.closest('.room'))return;drag=true;sx=e.clientX;sy=e.clientY;stx=tx;sty=ty;vp.classList.add('dragging');vp.setPointerCapture(e.pointerId)};vp.onpointermove=e=>{if(drag){tx=stx+e.clientX-sx;ty=sty+e.clientY-sy;apply()}};vp.onpointerup=()=>{drag=false;vp.classList.remove('dragging')};
document.querySelector('#plus').onclick=()=>setScale(scale*1.15);document.querySelector('#minus').onclick=()=>setScale(scale*.85);document.querySelector('#reset').onclick=()=>{scale=.78;tx=25;ty=55;apply()};
