function researchCandles(n=220){let p=62000,s=73;return Array.from({length:n},(_,i)=>{s=Math.imul(1664525,s)+1013904223>>>0;const noise=(s/4294967296-.48)*.018,regime=i<80?.002:i<145?-.0012:.0015;p=Math.max(1000,p*(1+regime+noise));return{time:i,close:p,volume:100+(s%80)}})}
document.querySelector('#runResearch').onclick=e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='CORRIENDO…';setTimeout(()=>{const candles=researchCandles(),bt=QCFResearch.backtest(candles,trendStrategy,{fee:.0006,slippage:.0005}),wf=QCFResearch.walkForward(candles,trendStrategy,{train:80,test:30,fee:.0006,slippage:.0005}),rets=bt.equity.slice(1).map((x,i)=>x/bt.equity[i]-1),mc=QCFResearch.monteCarlo(rets,300,42);document.querySelector('#btReturn').textContent=(bt.totalReturn*100).toFixed(1)+'%';document.querySelector('#btSharpe').textContent=bt.sharpe.toFixed(2);document.querySelector('#btDrawdown').textContent=(bt.maxDrawdown*100).toFixed(1)+'%';document.querySelector('#btWalk').textContent=wf.pass?'PASS':'REVIEW';document.querySelector('#researchStatus').textContent=`${wf.pass?'Walk-forward aprobado':'Revisión requerida'} · MC p05 ${(mc.p05*100).toFixed(1)}% · ${bt.trades} fills`;if(wf.pass)strategies.promote(trendStrategy.id);btn.disabled=false;btn.textContent='EJECUTAR'},450)};
function renderEngine(){floor.classList.toggle('paused',engine.state==='paused');floor.classList.toggle('halted',engine.state==='halted');document.querySelector('#engineState').textContent=engine.state.toUpperCase();document.querySelector('#engineState').style.color=engine.state==='running'?'var(--lime)':engine.state==='paused'?'var(--orange)':'var(--red)';document.querySelector('#engineDot').style.background=engine.state==='running'?'var(--lime)':engine.state==='paused'?'var(--orange)':'var(--red)';document.querySelector('#engineToggle').textContent=engine.state==='paused'?'▶ REANUDAR':'Ⅱ PAUSAR';document.querySelector('#killSwitch').classList.toggle('active',engine.state==='halted');document.querySelector('#riskGate').textContent=engine.state==='halted'?'LOCKED':'OPEN'}
function transitionEngine(next){try{engine.state=stateMachine.transition(next)}catch(e){return}renderEngine()}
document.querySelector('#engineToggle').onclick=()=>{if(engine.state==='halted')return;transitionEngine(engine.state==='paused'?'running':'paused')};document.querySelector('#killSwitch').onclick=()=>transitionEngine(engine.state==='halted'?'paused':'halted');document.querySelector('#scenario').onchange=e=>{engine.scenario=e.target.value;const map={normal:[42,'OPEN'],bull:[55,'OPEN'],crash:[180,'REVIEW'],depeg:[210,'REVIEW'],outage:[999,'LOCKED']},v=map[engine.scenario];engine.latency=v[0];document.querySelector('#latency').textContent=engine.latency+'ms';document.querySelector('#riskGate').textContent=v[1];document.querySelector('#feedHealth').textContent=engine.scenario==='outage'?'DOWN':engine.scenario==='depeg'?'DEGRADED':'HEALTHY';if(engine.scenario==='outage'&&engine.state!=='halted')transitionEngine('halted');runTrace()};setInterval(()=>{if(engine.state!=='running')return;engine.events+=Math.floor(Math.random()*4);document.querySelector('#eventCount').textContent=engine.events.toLocaleString('en-US').padStart(7,'0');const jitter=Math.round((Math.random()-.5)*8);document.querySelector('#latency').textContent=Math.max(1,engine.latency+jitter)+'ms';dataPlane.ingest({symbol:'BTCUSDT',price:68420+Math.random()*12,volume:8+Math.random()*5,timestamp:Date.now()},'exchange-a');const health=dataPlane.health('BTCUSDT');if(engine.scenario==='normal')document.querySelector('#feedHealth').textContent=health.status.toUpperCase()},1600);renderEngine();
function focusRoom(a){scale=Math.min(1.05,Math.max(.62,Math.min((vp.clientWidth-110)/a.w,(vp.clientHeight-140)/a.h)));tx=(vp.clientWidth-a.w*scale)/2-a.x*scale;ty=(vp.clientHeight-a.h*scale)/2-a.y*scale;apply()}
document.querySelector('#search').addEventListener('input',e=>{let q=e.target.value.toLowerCase().trim();document.querySelectorAll('.room').forEach((r,i)=>r.classList.toggle('highlight',q&&([areas[i].name,...areas[i].agents].join(' ').toLowerCase().includes(q))));});
function tick(){const d=new Date(),h=d.getHours(),phase=h<6||h>=20?'night':h<9||h>=17?'dawn':'day';document.querySelector('#time').textContent=d.toLocaleTimeString([], {hour12:false});document.querySelector('#phase').textContent=`LOCAL · ${phase==='night'?'NIGHT SHIFT':phase==='dawn'?'GOLDEN HOUR':'DAY SESSION'}`;floor.classList.remove('night','dawn','day');floor.classList.add(phase)}setInterval(tick,1000);tick();apply();setTimeout(()=>selectArea(areas[0]),300);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){detail.classList.remove('open');closeMenu();scale=.78;tx=25;ty=55;apply()}if(e.key==='+'||e.key==='=')setScale(scale*1.12);if(e.key==='-')setScale(scale*.88);if(e.key==='0'){scale=.78;tx=25;ty=55;apply()}});
